#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "trmm.h"


/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE *alpha,
		DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  *alpha = 1.5;
  for (i = 0; i < m; i++) {
    for (j = 0; j < i; j++) {
      A[i][j] = (DATA_TYPE)((i+j) % m)/m;
    }
    A[i][i] = 1.0;
    for (j = 0; j < n; j++) {
      B[i][j] = (DATA_TYPE)((n+(i-j)) % n)/n;
    }
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("B");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, B[i][j]);
    }
  POLYBENCH_DUMP_END("B");
  POLYBENCH_DUMP_FINISH;
}


/* Optional tuning parameter for cache blocking of the j-dimension.
   Can be overridden at compile time with -DTRMM_J_BLOCK=<value>. */
#ifndef TRMM_J_BLOCK
# define TRMM_J_BLOCK 64
#endif


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_trmm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

  /* Local aliases with explicit restrict qualifiers help the
     compiler assume that A and B do not alias, improving
     vectorization and scheduling. */
  DATA_TYPE (*restrict A_)[M] = A;
  DATA_TYPE (*restrict B_)[N] = B;

// BLAS parameters
// SIDE   = 'L'
// UPLO   = 'L'
// TRANSA = 'T'
// DIAG   = 'U'
// => Form  B := alpha*A**T*B.
// A is MxM
// B is MxN
#pragma scop
  /* Optimized loop structure:
   *
   * Original computation:
   *   for i
   *     for j
   *       for k=i+1..M-1
   *         B[i][j] += A[k][i] * B[k][j];
   *       B[i][j] *= alpha;
   *
   * We perform two key transformations:
   *   1. Interchange the (j,k) loops to obtain (i, k, j), which
   *      makes the innermost loop traverse B[i][:] and B[k][:]
   *      with unit stride (row-major contiguous), greatly
   *      improving cache use and vectorization opportunities.
   *   2. Factor the multiplication by alpha into a separate pass.
   *      This is safe because every B[i][j] element is updated
   *      independently, and B[k][j] is only read (never written)
   *      before it is used in another row's update.
   *
   * Semantically we preserve:
   *   B_out[i][j] = alpha * ( B_in[i][j]
   *                           + sum_{k=i+1..M-1} A[k][i] * B_in[k][j] )
   * exactly as in the original kernel.
   */

  /* Triangular update phase: B[i,:] += sum_{k>i} A[k,i] * B[k,:]. */
  for (i = 0; i < _PB_M; i++) {
    for (k = i + 1; k < _PB_M; k++) {
      DATA_TYPE a_ki = A_[k][i]; /* loaded once per (i,k) */

      /* Block the j-loop to keep slices of B[i,:] and B[k,:]
         in the L1/L2 caches when N is large.  The compiler
         still sees a simple contiguous inner loop over j. */
      for (int jj = 0; jj < _PB_N; jj += TRMM_J_BLOCK) {
        int j_end = jj + TRMM_J_BLOCK;
        if (j_end > _PB_N)
          j_end = _PB_N;

        /* Contiguous, vectorization-friendly inner loop.  The
           ivdep pragma tells GCC that there are no loop-carried
           dependencies along j, enabling aggressive SIMD. */
        #pragma GCC ivdep
        for (j = jj; j < j_end; j++) {
          B_[i][j] += a_ki * B_[k][j];
        }
      }
    }
  }

  /* Final scaling phase: B[i,j] *= alpha.
     Equivalent to doing the scaling in the original inner (i,j)
     loop, but separated to keep the main update phase simpler
     and more vectorizable. */
  for (i = 0; i < _PB_M; i++) {
    #pragma GCC ivdep
    for (j = 0; j < _PB_N; j++) {
      B_[i][j] *= alpha;
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_trmm (m, n, alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(B)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
