	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, B[i][j]);
    }
  POLYBENCH_DUMP_END("B");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_trmm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

  /* Create local restrict-qualified views of the PolyBench arrays.
     This tells the compiler that A_ and B_ do not alias each other,
     which helps optimization and vectorization. */
  DATA_TYPE (*restrict A_)[M] = (DATA_TYPE (*)[M])A;
  DATA_TYPE (*restrict B_)[N] = (DATA_TYPE (*)[N])B;

  const int Mdim = _PB_M;
  const int Ndim = _PB_N;

  /* Tunable blocking factor along the column (N) dimension.
     Can be overridden at compile time, e.g., with:
       -DTRMM_BLOCK_J=128
     The default 64 is chosen to fit typical L1/L2 cache lines well. */
#ifndef TRMM_BLOCK_J
# define TRMM_BLOCK_J 64
#endif
  const int block_j = TRMM_BLOCK_J;

//BLAS parameters
//SIDE   = 'L'
//UPLO   = 'L'
//TRANSA = 'T'
//DIAG   = 'U'
// => Form  B := alpha*A**T*B.
// A is MxM
// B is MxN
#pragma scop
  /*
   * Original algorithm (schematically):
   *
   *   for i
   *     for j
   *       for k = i+1..M-1
   *         B[i][j] += A[k][i] * B[k][j];
   *       B[i][j] *= alpha;
   *
   * For each (i,j), the sum over k is computed in increasing k order,
   * and then scaled by alpha.
   *
   * Optimized algorithm:
   *
   *   - Keep i as the outermost loop to preserve the triangular
   *     dependency structure across rows.
   *   - Make j the innermost loop to walk contiguous memory in B.
   *   - Introduce a tunable block in the j-dimension to improve cache
   *     locality.
   *   - Move the scaling by alpha to a separate (but still per-row)
   *     loop, after the accumulation over k. For each (i,j), the order
   *     of operations over k is unchanged, so floating-point results
   *     are bitwise identical to the original code.
   */
  for (i = 0; i < Mdim; ++i)
  {
    /* Pointer to the current destination row. */
    DATA_TYPE *Bi = B_[i];

    /* Process the row in column blocks to improve cache behavior. */
    for (int jj = 0; jj < Ndim; jj += block_j)
    {
      const int j_end = (jj + block_j < Ndim) ? (jj + block_j) : Ndim;

      /* Accumulate A^T * B into row i over the current column block:
         B[i][j] += sum_{k=i+1..M-1} A[k][i] * B[k][j] */
      for (k = i + 1; k < Mdim; ++k)
      {
        const DATA_TYPE aik = A_[k][i];
        const DATA_TYPE *Bk = B_[k];

        DATA_TYPE *Bi_block = Bi + jj;
        const DATA_TYPE *Bk_block = Bk + jj;

        /* Inner-most loop walks contiguous elements of B's rows.
           Each (i,j) element is updated independently, so it is
           safe to tell the compiler to ignore assumed dependencies
           across j iterations for vectorization. */
#pragma GCC ivdep
        for (j = jj; j < j_end; ++j)
        {
          *Bi_block += aik * (*Bk_block);
          ++Bi_block;
          ++Bk_block;
        }
      }

      /* Scale the updated part of row i by alpha.
         This is mathematically equivalent to scaling inside the
         original j-loop because alpha is applied once per element
         after the full sum over k. */
      DATA_TYPE *Bi_block = Bi + jj;
#pragma GCC ivdep
      for (j = jj; j < j_end; ++j)
      {
        *Bi_block *= alpha;
        ++Bi_block;
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_trmm (m, n, alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(B)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
