kernel_trmm(int m, int n,
            DATA_TYPE alpha,
            DATA_TYPE POLYBENCH_2D(A,M,M,m,m) restrict,
            DATA_TYPE POLYBENCH_2D(B,M,N,m,n) restrict)
{
  /* Use PolyBench's possibly reduced problem sizes. */
  const int _m = _PB_M;
  const int _n = _PB_N;

  /* Keep alpha in a local const to favor register allocation. */
  const DATA_TYPE alpha_local = alpha;

#pragma scop
  for (int i = 0; i < _m; ++i)
  {
    /* Pointer to the i-th row of B: updated in place. */
    DATA_TYPE *restrict Bi = B[i];

    /* First, accumulate contributions from rows k > i into row i.
       This computes:
         Bi[j] <- Bi[j] + sum_{k=i+1..M-1} A[k][i] * B[k][j]
       for all j, exactly as in the original code, but with a more
       cache-friendly access pattern (contiguous in j). */
    for (int k = i + 1; k < _m; ++k)
    {
      const DATA_TYPE a_ki = A[k][i];         /* Scalar reused across j. */
      const DATA_TYPE *restrict Bk = B[k];    /* Read-only source row.   */

      int j = 0;

#if TRMM_J_UNROLL >= 4
      /* Unrolled main j-loop. The unroll factor is tunable via the
         TRMM_J_UNROLL macro; here we only specialize for >= 4. */
      for (; j <= _n - 4; j += 4)
      {
        Bi[j+0] += a_ki * Bk[j+0];
        Bi[j+1] += a_ki * Bk[j+1];
        Bi[j+2] += a_ki * Bk[j+2];
        Bi[j+3] += a_ki * Bk[j+3];
      }
#endif

      /* Remainder loop for any leftover columns. */
      for (; j < _n; ++j)
      {
        Bi[j] += a_ki * Bk[j];
      }
    }

    /* Then apply the unit diagonal scaling:
         Bi[j] <- alpha * Bi[j]
       This is mathematically identical to the original
       "Bi[j] = alpha * Bi[j]" performed inside the j-loop, but
       hoisted and separated to improve locality and vectorization.
       The sequence of operations for each Bi[j] (adds over k,
       followed by one multiply by alpha) is unchanged. */
    int j = 0;

#if TRMM_J_UNROLL >= 4
    for (; j <= _n - 4; j += 4)
    {
      Bi[j+0] *= alpha_local;
      Bi[j+1] *= alpha_local;
      Bi[j+2] *= alpha_local;
      Bi[j+3] *= alpha_local;
    }
#endif

    for (; j < _n; ++j)
    {
      Bi[j] *= alpha_local;
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_trmm (m, n, alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(B)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
