/* ------------------------------------------------------------------------
 * Tunable kernel parameters.
 *
 * TRMM_K_BLOCK controls the blocking factor along the k-dimension of the
 * triangular loop in the main kernel.  It is exposed as a macro so it can
 * be tuned for a particular cache hierarchy (e.g., via -DTRMM_K_BLOCK=64).
 *
 * The value must be strictly positive.
 * ----------------------------------------------------------------------*/
#ifndef TRMM_K_BLOCK
#  define TRMM_K_BLOCK 64
#endif


/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE *alpha,
		DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  /* Local aliases with explicit sizes to help the compiler reason about
   * the access patterns.  In function parameters, a VLA such as
   * DATA_TYPE A[m][m] decays to a pointer to m-element arrays. */
  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE (*restrict B_)[n] = B;

  *alpha = (DATA_TYPE)1.5;

  /* Precompute inverses to avoid repeated divisions in the loops. */
  const DATA_TYPE inv_m = (DATA_TYPE)1.0 / (DATA_TYPE)m;
  const DATA_TYPE inv_n = (DATA_TYPE)1.0 / (DATA_TYPE)n;

  for (i = 0; i < m; i++) {
    DATA_TYPE *restrict Ai = A_[i];
    DATA_TYPE *restrict Bi = B_[i];

    /* Strictly lower-triangular part of A. */
    for (j = 0; j < i; j++) {
      Ai[j] = (DATA_TYPE)((i + j) % m) * inv_m;
    }

    /* Unit diagonal. */
    Ai[i] = (DATA_TYPE)1.0;

    /* Full row of B. */
    for (j = 0; j < n; j++) {
      Bi[j] = (DATA_TYPE)((n + (i - j)) % n) * inv_n;
    }
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("B");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, B[i][j]);
    }
  POLYBENCH_DUMP_END("B");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_trmm [[gnu::flatten, gnu::noinline]] (int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k, kk;

  /* Local restricted aliases to help the optimizer with alias analysis and
   * enable better vectorization.  The PolyBench allocation scheme ensures
   * that A and B do not alias, so adding restrict here preserves the
   * semantics for all well-defined program executions. */
  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE (*restrict B_)[n] = B;

  const DATA_TYPE alpha_local = alpha;

  // BLAS parameters
  // SIDE   = 'L'
  // UPLO   = 'L'
  // TRANSA = 'T'
  // DIAG   = 'U'
  // => Form  B := alpha*A**T*B.
  // A is MxM (unit lower triangular)
  // B is MxN
  //
  // Optimized strategy:
  // - Preserve the original mathematical computation:
  //     for each (i,j), accumulate sum over k = i+1..M-1 in ascending order
  //     and then scale by alpha.
  // - Improve temporal locality and reduce repeated memory traffic on B[i][j]
  //   by keeping the accumulation in a scalar "sum" instead of repeatedly
  //   updating B[i][j] in memory inside the k-loop.
  // - Introduce a tunable blocking factor along k (TRMM_K_BLOCK) to improve
  //   cache behavior for A[k][i] and B[k][j] when M is large.
#pragma scop
  for (i = 0; i < _PB_M; i++)
  {
    /* Pointer to the current row of B; makes the inner loops cheaper and
     * easier to vectorize. */
    DATA_TYPE *restrict Bi = B_[i];

    for (j = 0; j < _PB_N; j++)
    {
      /* Start from the implicit diagonal contribution: A[i][i] == 1, so
       * we initialize the accumulator with B[i][j].  This matches the
       * original algorithm which used B[i][j] as the running value. */
      DATA_TYPE sum = Bi[j];

      /* Block the k-loop to improve cache reuse of A and B across the k
       * dimension.  The order of k (and thus the order of floating-point
       * operations) remains strictly increasing, preserving numerical
       * semantics of the original code. */
      for (kk = i + 1; kk < _PB_M; kk += TRMM_K_BLOCK)
      {
        int kend = kk + TRMM_K_BLOCK;
        if (kend > _PB_M)
          kend = _PB_M;

        /* No loop-carried dependencies along k: each iteration reads
         * A_[k][i] and B_[k][j] and accumulates into the scalar "sum".
         * This is a good target for auto-vectorization. */
        #pragma GCC ivdep
        for (k = kk; k < kend; k++)
        {
          sum += A_[k][i] * B_[k][j];
        }
      }

      /* Final scaling by alpha, as in the original kernel. */
      Bi[j] = alpha_local * sum;
    }
  }
#pragma endscop

}


